public static boolean valid(int[] coins, int total) {
    int[] coinTypes = new int[]{1, 5, 10, 50, 100, 500};
    for (int i = 5; i >= 0; i--) {
        while (total >= coinTypes[i] && coins[i] > 0) {
            total -= coinTypes[i];
            coins[i]--;
        }
    }
    if (total > 0) {
        return false;
    }
    return true;
}
